mapper.update:
    /* Attd04Mapper.saveAttdStdTimeRule */
    INSERT INTO TB_ATTD_STD_TIME_RULE (
		CMPNY_CD
		, STD_TIME_RULE_TYPE
		, STD_TIME_TYPE
		, INSERT_NO 
		, INSERT_DATE
		, UPDATE_NO
		, UPDATE_DATE
	)
    VALUES (
		#{gvCmpnyCd}
		, #{stdTimeRuleType}
		, #{stdTimeType}
		, #{gvUserCd}
		, NOW()
		, #{gvUserCd}
		, NOW()
	) AS NEW
	ON DUPLICATE KEY UPDATE
		STD_TIME_TYPE	= NEW.STD_TIME_TYPE
		, UPDATE_NO     = NEW.UPDATE_NO
		, UPDATE_DATE   = NOW()

mapper.select:
    /* Attd04Mapper.selectHistIdx */
    SELECT
    	COUNT(*)
	FROM TB_ATTD_STD_TIME_RULE_HIS
	WHERE CMPNY_CD = #{gvCmpnyCd}

mapper.insert:
    /* Attd04Mapper.saveAttdStdTimeRuleHist */
    INSERT INTO TB_ATTD_STD_TIME_RULE_HIS (
		HIST_IDX
		, CMPNY_CD
		, STD_TIME_RULE_TYPE
		, STD_TIME_TYPE
		, INSERT_NO 
		, INSERT_DATE
	)
    VALUES (
		#{histIdx}
		, #{gvCmpnyCd}
		, #{stdTimeRuleType}
		, #{stdTimeType}
		, #{gvUserCd}
		, NOW()
	)
